+// Shortcuts that make work look done. Lines the run added or removed are matched by pattern; this is a
+// reminder aid, not a verdict, so each finding is only a flag the user can read.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; text?: string };
+export const findingText = (f: Finding) => `${f.rule} ${f.path}${f.text ? `: ${f.text}` : ''}`;
+
+import type { EventOf, SessionEvent } from '../types.ts';
+import type { TextEdit } from '../tools/edit.ts';
+
+const CODE = /\.(m?[jt]sx?|cjs|py|go|rs|rb|java|kt|cs|php|c|cc|cpp|h|hpp|swift|sh)$/;
+const TEST = /(\.test\.|\.spec\.|_test\.|(^|\/)test_[^/]*$|(^|\/)tests?\/)/;
+const SKIP = /\b(test|it|describe)\.skip\(|\bxit\(|\bxdescribe\(|\bt\.Skip(Now)?\(|@pytest\.mark\.skip|\bpytest\.skip\(/;
+const ASSERT = /\bassert\b|\bexpect\(|\bt\.(Error|Errorf|Fatal|Fatalf)\(/;
+const SUPPRESS = /@ts-(ignore|nocheck|expect-error)|eslint-disable|# type: ignore|# noqa|# pylint: disable|\/\/ nolint/;
+const SWALLOW = /\bcatch\s*(\([^)]*\))?\s*\{\s*\}|^\s*except\b[^:]*:\s*pass\s*$/;
+const TYPE_ESCAPE = /\bas any\b/;
+const STUB = /NotImplementedError|throw new Error\(\s*['"`]not implemented|\bunimplemented!\(|\btodo!\(/i;
+
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', SUPPRESS],
+  ['swallowed-error', SWALLOW],
+  ['type-escape', TYPE_ESCAPE],
+  ['stub', STUB],
+];
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    const isTest = TEST.test(c.path);
+    if (isTest && c.deleted) {
+      out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (isTest && c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length)
+      out.push({ rule: 'test-weakened', path: c.path });
+    if (isTest && c.added.some((l) => SKIP.test(l))) out.push({ rule: 'test-skipped', path: c.path });
+    if (!CODE.test(c.path)) continue;
+    for (const line of c.added)
+      for (const [rule, re] of LINE_RULES) if (re.test(line)) out.push({ rule, path: c.path, text: line.trim() });
+  }
+  return out;
+}
+
+// Without snapshots, the changes are what edit and write calls asked for.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  const out: FileChange[] = [];
+  for (const e of events) {
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const intent = intents.get(e.callId);
+    if (!intent) continue;
+    const path = String(intent.input.path ?? '');
+    if (intent.tool === 'write') out.push({ path, added: String(intent.input.content ?? '').split('\n'), removed: [], deleted: false });
+    if (intent.tool !== 'edit') continue;
+    const edits = (Array.isArray(intent.input.edits) ? intent.input.edits : []) as TextEdit[];
+    out.push({ path, added: edits.flatMap((x) => x.new_text.split('\n')), removed: edits.flatMap((x) => x.old_text.split('\n')), deleted: false });
+  }
+  return out;
+}
+
+// Reads a `git diff -U0` patch (diff --git headers, hunks) into per-file changes.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    if (line.startsWith('diff --git ')) {
+      const m = /^diff --git a\/(.*) b\/(.*)$/.exec(line);
+      cur = { path: m?.[2] ?? line, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (!inHunk) continue;
+    else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
