--- a/src/core/trust/slop.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/src/core/trust/slop.ts	2026-10-28 07:04:09.337151975 +0000
@@ -0,0 +1,56 @@
+// Shortcuts that make work look done. They are flags for the model and the user, not refusals: a finding is
+// reminded once, then the claim stands and the flag stays in the evidence.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; line?: string };
+
+const CODE = /\.(m?[jt]sx?|py|go|rs|rb|java|kt|cs|php|c|cc|cpp|h|hpp|swift)$/;
+const TEST = /(\.(test|spec)\.\w+|_test\.\w+|(^|\/)test_[^/]*\.py|(^|\/)tests?\/)/;
+const ASSERT = /\bassert\w*|\bexpect\(|\.should\b|\bt\.(Error|Fatal)/;
+const SKIP = /\b(test|it|describe)\.(skip|todo)\(|\bxit\(|\bxdescribe\(|\bt\.Skip\(|@pytest\.mark\.skip/;
+
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', /@ts-(ignore|expect-error|nocheck)|eslint-disable|# type: ignore|# noqa|# pylint: disable|\/\/\s*nolint/],
+  ['swallowed-error', /catch\s*(\([^)]*\))?\s*\{\s*\}|\.catch\(\s*\(\)\s*=>\s*\{\s*\}\)|except[^:]*:\s*pass\b/],
+  ['type-escape', /\bas any\b|: any\b/],
+  ['stub', /not implemented|NotImplementedError|unimplemented!|todo!\(\)/i],
+];
+
+const count = (lines: string[], re: RegExp) => lines.filter((l) => re.test(l)).length;
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    if (TEST.test(c.path)) {
+      if (c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+      else if (count(c.added, ASSERT) < count(c.removed, ASSERT)) out.push({ rule: 'test-weakened', path: c.path });
+      for (const line of c.added) if (SKIP.test(line)) out.push({ rule: 'test-skipped', path: c.path, line });
+    }
+    if (!CODE.test(c.path)) continue;
+    for (const line of c.added)
+      for (const [rule, re] of LINE_RULES) if (re.test(line)) out.push({ rule, path: c.path, line });
+  }
+  return out;
+}
+
+export const slopFlag = (f: Finding) => (f.line === undefined ? `${f.rule} ${f.path}` : `${f.rule} ${f.path}: ${f.line.trim()}`);
+
+// Reads a `git diff -p -U0` patch. Header lines (---, +++, index, mode) are skipped until the first hunk.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (!inHunk) {
+      if (line.startsWith('deleted file mode')) cur.deleted = true;
+    } else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
