+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { bulkDiscount } from '../src/pricing/discounts/bulk.ts';
+import { totals } from '../src/order/total.ts';
+
+describe('pricing rules from README', () => {
+  test('bulk tiers start at 10 and 50 units inclusive', () => {
+    expect(bulkDiscount(9, 1000)).toBe(0);
+    expect(bulkDiscount(10, 1000)).toBe(50);
+    expect(bulkDiscount(49, 1000)).toBe(50);
+    expect(bulkDiscount(50, 1000)).toBe(100);
+  });
+
+  test('UK free shipping starts at 4000, not 4500', () => {
+    // 2 bags = 4400 >= 4000 ships free; 1 bag = 2200 pays 700
+    expect(totals(cart('UK', [['BAG', 2]])).shipping).toBe(0);
+    expect(totals(cart('UK', [['BAG', 1]])).shipping).toBe(700);
+  });
+
+  test('bulk units are counted per SKU across lines', () => {
+    // 6 + 6 mugs = 12 units -> 5% off 12 * 450 = 5400 -> 270; subtotal 5130
+    const t = totals(cart('US', [['MUG', 6], ['MUG', 6]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.subtotal).toBe(5130);
+    expect(t.shipping).toBe(0);
+  });
+
+  test('shipping threshold uses the subtotal after coupon', () => {
+    // 12 mugs: subtotal 5130 is free shipping, but SAVE10 takes it to 4617 -> pays 800
+    const t = totals(cart('US', [['MUG', 12]], 'SAVE10'));
+    expect(t.coupon).toBe(513);
+    expect(t.shipping).toBe(800);
+  });
+});

