+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+describe('pricing rules', () => {
+  test('bulk discount starts at 10 units', () => {
+    // 10 mugs = 4500; 5% off = 4275; under 5000 so shipping 800; tax 7% of 5075 = 355.25 -> 355
+    expect(totals(cart('US', [['MUG', 10]]))).toMatchObject({ subtotal: 4275, coupon: 0, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('bulk discount at 50 units uses the 10% tier', () => {
+    // 50 mugs = 22500; 10% off = 20250; free shipping; tax 7% of 20250 = 1417.5 -> 1418
+    expect(totals(cart('US', [['MUG', 50]]))).toMatchObject({ subtotal: 20250, shipping: 0, tax: 1418, total: 21668 });
+  });
+
+  test('UK free shipping threshold is 4000', () => {
+    // 2 bags = 4400 >= 4000 -> free shipping
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ subtotal: 4400, shipping: 0 });
+  });
+
+  test('shipping threshold uses the discounted subtotal', () => {
+    // 10 x 520 = 5200 undiscounted (free), but 5% off gives 4940 < 5000 -> shipping 800
+    // tax 7% of 5740 = 401.8 -> 402
+    const c = { lines: [{ sku: 'X', quantity: 10, unitPrice: 520 }], region: 'US' };
+    expect(totals(c)).toMatchObject({ subtotal: 4940, shipping: 800, tax: 402, total: 6142 });
+  });
+
+  test('lines of the same sku are merged before bulk pricing', () => {
+    // 6 + 4 mugs = 10 units -> 5% bulk discount applies to the merged line
+    const merged = totals(cart('US', [['MUG', 6], ['MUG', 4]]));
+    expect(merged).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+    expect(merged.lines).toHaveLength(1);
+  });
+});

